  zh: {
    title: "扑克术语表 — 德州扑克词汇 — PokerTH",
    desc: "德州扑克术语的含义，从 all-in 到 wheel：盲注、踢脚牌、补牌、底池赔率、set 与 trips、边池和摊牌，用平实的语言解释。",
    ldHeadline: "扑克术语表 — 德州扑克词汇解释",
    ldDesc: "德州扑克术语表，从 all-in 到 wheel。",
    h1: "扑克术语表 — 德州扑克词汇",
    lead: "你在德州扑克牌桌上、聊天里以及 PokerTH 本身会遇到的词。五个动作词——Fold、Check、Call、Raise 和 All-In——在全部 45 种界面语言中都保持英文，因为全世界的牌桌都是这样。",
    terms: [
      ["全下", "押上你所有的筹码。你只能赢下自己出资的那部分底池，其余进入边池。"],
      ["底注", "每位玩家在发牌前额外支付的小额强制下注，与盲注并存。部分锦标赛的后期级别会使用。"],
      ["后门听牌", "需要转牌和河牌同时配合才能成型的听牌，比如再来两张红心凑同花。"],
      ["爆冷输牌", "在你占据压倒性优势的一手牌里输掉。"],
      ["大盲注", "两个强制下注中较大的一个，由庄家按钮左侧第二位玩家支付。锦标赛的筹码量通常以大盲注计算。"],
      ["盲注", "开启每一手牌的两个强制下注，让玩家有东西可争。在 PokerTH 中它们按时上涨。"],
      ["公共牌", "五张公共牌，所有人共用。"],
      ["泡沫圈", "锦标赛中刚好在有奖或计分名次开始之前的那个阶段。"],
      ["庄家按钮", "标记名义庄家的圆片。按钮位的玩家在翻牌后最后行动，是牌桌上最好的位置。"],
      ["跟注", "跟上当前的下注额，不多不少。"],
      ["过牌", "不下注而把行动权交给下一位。仅当本轮尚无人下注时可行。"],
      ["过牌加注", "先过牌，等别人下注后再加注。用强牌做大底池的手段。"],
      ["公共牌", "所有人都可以使用的五张明牌，依次以翻牌、转牌、河牌发出。"],
      ["连牌", "两张点数相连的底牌，例如 8-9。同花连牌还共用同一花色。"],
      ["听牌", "尚未成型的牌，还差一张或几张才够强——四张同花、四张顺子。"],
      ["无望听牌", "手里的听牌即使成型也赢不了。"],
      ["胜率", "考虑还未发出的牌之后，你在底池中应占的份额——实际上就是你从此刻起获胜的频率。"],
      ["翻牌", "最先发出的三张公共牌，一次性亮出。"],
      ["弃牌", "放弃这手牌，连同已经投入的所有筹码。"],
      ["免费赛", "不收报名费的锦标赛。在 PokerTH 中每一桌都是如此，因为这里根本没有钱。"],
      ["单挑", "只剩两名玩家的一手牌，或锦标赛的该阶段。"],
      ["底牌", "你的两张私有牌。"],
      ["踢脚牌", "组成牌型之后剩下的最大一张牌，用于分出同一牌型之间的高下。"],
      ["跛入", "翻牌前不加注，只跟上大盲注就进入底池。"],
      ["盖牌", "摊牌时把牌面朝下丢掉，而不亮出来。"],
      ["坚果牌", "在当前公共牌下可能出现的最大牌型。无法被击败，只能打平。"],
      ["杂色", "两张花色不同的底牌。"],
      ["补牌", "牌堆里还能让你成为赢家的那些牌。四张同花时还剩九张补牌。"],
      ["超对", "手中的对子大过公共牌上的任何一张。"],
      ["口袋对", "两张点数相同的底牌。"],
      ["底池", "当前这手牌所争夺的筹码。"],
      ["底池赔率", "底池给你开出的价格：你需要跟注多少，对比你可能赢得多少。"],
      ["翻牌前", "第一轮下注，此时尚未发出任何公共牌。"],
      ["彩虹面", "三种不同花色的翻牌，使得立刻成同花听牌成为不可能。"],
      ["加注", "抬高当前的下注额。在无限注中，可以加到你的全部筹码。"],
      ["再加注", "对一次加注再加注。"],
      ["河牌", "第五张也是最后一张公共牌，以及随之而来的下注轮。"],
      ["暗三条", "由手中的口袋对加上公共牌中的一张组成的三条——藏得很好，不像 trips。"],
      ["短筹码", "相对盲注偏小的筹码量，除了弃牌或全下几乎别无选择。"],
      ["摊牌", "最后一轮下注结束后亮出剩余的牌，决定谁获胜。"],
      ["边池", "当一名玩家全下而其他人继续在该金额之上下注时，另行产生的底池。"],
      ["坐满即开赛", "座位坐满即开始的锦标赛，而非固定时间开赛。PokerTH 的每一局都是这种。"],
      ["慢打", "拿着强牌却打得很弱，好把对手留在底池里。"],
      ["小盲注", "较小的强制下注，由庄家按钮紧邻左侧的玩家支付。"],
      ["平分底池", "在实力相同的牌之间平分的底池。德州扑克中花色从不用来分出高下。"],
      ["筹码量", "一名玩家面前的筹码。"],
      ["加大盲", "发牌前可选的盲目加注。PokerTH 中不使用。"],
      ["同花", "两张花色相同的底牌。"],
      ["上头", "因为懊恼而打得很差，通常发生在爆冷输牌之后。"],
      ["明三条", "由一张底牌和公共牌上的一对组成的三条。三张里有两张所有人都看得见。"],
      ["转牌", "第四张公共牌，以及随之而来的下注轮。"],
      ["枪口位", "翻牌前最先行动的位置，紧邻大盲注左侧。"],
      ["价值下注", "为了让更差的牌来跟注而下的注，而不是为了逼谁弃牌。"],
      ["轮子", "A-2-3-4-5 的顺子，其中 A 当作最小。存在的最弱顺子。"]
    ],
    footer: function (h, c) { return "还不太清楚一手牌是怎么走的？<a href=\"{rules}\">规则</a>从盲注一路讲到摊牌，<a href=\"{hands}\">牌型大小</a>则列出什么牌大过什么牌。".replace('{rules}', h('rules', c)).replace('{hands}', h('hands', c)); }
  },

